<?php $editAddress=isset($_GET['edit'])?query('SELECT * FROM user_addresses WHERE id=? AND user_id=?',[(int)$_GET['edit'],$u['id']])->fetch():null; ?>
<form class="form-panel" method="post" action="/api/action" data-ajax data-reload><?=csrf_field()?><input type="hidden" name="action" value="address"><input type="hidden" name="id" value="<?=e($editAddress['id']??0)?>"><h3><?=$editAddress?'Edit your address':'Add an address'?></h3><div class="form-grid"><?php foreach(['label','address','city','province','country','postal_code'] as $key): ?><label><?=e(ucwords(str_replace('_',' ',$key)))?><input name="<?=e($key)?>" value="<?=e($editAddress[$key]??'')?>" required maxlength="<?=$key==='address'?500:($key==='postal_code'?20:60)?>"></label><?php endforeach ?></div><button class="btn">Save address</button></form>
